def settext(p,text,highlight=False):
 assert not p._p.xpath('.//m:oMath | .//w:drawing'),'Refuse to overwrite math/images'
 rpr=deepcopy(p.runs[0]._r.rPr) if p.runs and p.runs[0]._r.rPr is not None else None
 for c in list(p._p):
  if c.tag.endswith('}pPr'):continue
  p._p.remove(c)
 r=p.add_run(text)
 if rpr is not None:r._r.insert(0,rpr)
 if highlight:r.font.highlight_color=WD_COLOR_INDEX.YELLOW

def math_fingerprint(d):
 from lxml import etree
 return [hashlib.sha256(etree.tostring(e,method='c14n')).hexdigest() for p in d.paragraphs for e in p._p.xpath('.//m:oMath')]
def image_hashes(path):
 with zipfile.ZipFile(path) as z:return {n:hashlib.sha256(z.read(n)).hexdigest() for n in z.namelist() if n.startswith('word/media/')}

def apply(highlight=False):
 d=Document(SOURCE);ps=list(d.paragraphs);audit=[];oldmath=math_fingerprint(d)
 for idx,new in REVISIONS.items():
  old=ps[idx].text;settext(ps[idx],new,highlight);audit.append(dict(kind='paragraph',original_paragraph_index=idx,before=old,after=new))
 for ti,ri,ci,new in CELL_EDITS:
  c=d.tables[ti].rows[ri].cells[ci];old=c.text;settext(c.paragraphs[0],new,highlight);audit.append(dict(kind='table_cell',table=ti,row=ri,column=ci,before=old,after=new))
 # Distinguish CG proxy events from physical foot contact in the perturbation table.
 for ri in range(1,len(d.tables[7].rows)):
  c=d.tables[7].rows[ri].cells[2];old=c.text;new=old.replace('Reference contact:','CG reference event:').replace('No reference contact by planned end;','No CG reference event by planned end;')
  if new!=old:settext(c.paragraphs[0],new,highlight);audit.append(dict(kind='table_cell',table=7,row=ri,column=2,before=old,after=new))
 for idx in sorted(DELETE,reverse=True):
  audit.append(dict(kind='deleted_redundant_paragraph',original_paragraph_index=idx,before=ps[idx].text,after=''));ps[idx]._p.getparent().remove(ps[idx]._p)
 # Remove literal Markdown emphasis markers left in the source bibliography.
 for idx in range(165,177):
  p=ps[idx]
  if '*' in p.text:
   old=p.text;settext(p,old.replace('*',''),highlight);audit.append(dict(kind='bibliography_typography',original_paragraph_index=idx,before=old,after=p.text))
 # Keep the abstract on its own page; keywords and the body start on page two.
 ps[6].paragraph_format.page_break_before=True
 audit.append(dict(kind='format',target='Keywords paragraph',before='No explicit page break',after='Start body page after abstract'))
 from docx.shared import Pt
 from docx.enum.text import WD_ALIGN_PARAGRAPH
 for sec in d.sections:
  hp=sec.header.paragraphs[0];hp.text='Team TBA | Problem A';hp.alignment=WD_ALIGN_PARAGRAPH.RIGHT
  for run in hp.runs:run.font.size=Pt(9)
 audit.append(dict(kind='format',target='Running header',before='Blank',after='Team TBA | Problem A; team number remains a placeholder'))
 assert math_fingerprint(d)==oldmath,'Math changed'
 output=B/'reports'/('TBA_A_Draft03_TextMarked.docx' if highlight else'TBA_A_Draft03_TextRevised.docx');d.save(output)
 assert image_hashes(output)==image_hashes(SOURCE),'Image bytes changed'
 if not highlight:
  (B/'results/data/text_changes.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2))
  summary=dict(original_body_words=sum(len(p.text.split()) for p in Document(SOURCE).paragraphs),revised_body_words=sum(len(p.text.split()) for p in d.paragraphs),abstract_words=sum(len(ps[i].text.split()) for i in [3,4,5]),change_records=len(audit),math_objects=len(oldmath),math_preserved=True,image_files=len(image_hashes(SOURCE)),images_preserved=True,tables=len(d.tables),baseline='Uploaded TBA_A_Draft02.docx; virtual three-engine, wind-free M0 scenario; no v13 data substitution')
  assert summary['abstract_words']<=300
  (B/'results/data/editorial_validation.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2));print(json.dumps(summary,ensure_ascii=False,indent=2))
 return output
